INSERT INTO producer
    (type, name_ko, name_en, country, region, region_code, website, founded_year,
     description_ko, description_en, search_keywords, created_at, updated_at)
SELECT
    'OTHER', seed.name_ko, seed.name_en, seed.country, seed.region, seed.region_code,
    seed.website, seed.founded_year, seed.description_ko, seed.description_en,
    seed.search_keywords, NOW(6), NOW(6)
FROM tmp_korean_soju_producer_seed seed
WHERE NOT EXISTS (
    SELECT 1
    FROM producer existing
    WHERE existing.country = seed.country
      AND (
          existing.name_ko = seed.name_ko
          OR LOWER(existing.name_en) = LOWER(seed.name_en)
      )
);

DROP TABLE tmp_korean_soju_producer_seed;
